import React, { PropsWithChildren, useContext } from 'react';

import { Table } from '../hooks/useTable/types.js';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const DataTableV2Context = React.createContext<Table<any> | null>(null);

export function DataTableV2ContextProvider<T>(
  props: PropsWithChildren<{ value: Table<T> }>,
) {
  return (
    <DataTableV2Context.Provider value={props.value}>
      {props.children}
    </DataTableV2Context.Provider>
  );
}

export function useDataTableV2<T>() {
  const table = useContext<Table<T> | null>(DataTableV2Context);

  // Typescript assertion function, as in the context, the table will
  // always be defined.
  if (table === null) {
    throw new Error('Table instance is not defined in context.');
  }

  return table;
}
